examples.template:
MonarchSecurityAlertCard(
    alerts,
    onAction: { _ in },
    onMarkRead: { id in
        if let index = alerts.firstIndex(where: { $0.id == id }) { alerts[index].isRead = true }
    },
    onMarkAllRead: {
        for index in alerts.indices { alerts[index].isRead = true }
    },
    onDismiss: { id in alerts.removeAll { $0.id == id } }
)

examples.setupTemplate:
@State private var alerts = [
    MonarchSecurityAlert(id: {{alerts.0.id}}, title: {{alerts.0.title}}, description: {{alerts.0.description}}, severity: {{alerts.0.severity|case}}, date: Date(timeIntervalSinceNow: -{{alerts.0.hoursAgo}} * 3600), actionTitle: {{alerts.0.action}}),
    MonarchSecurityAlert(id: {{alerts.1.id}}, title: {{alerts.1.title}}, severity: {{alerts.1.severity|case}}, date: Date(timeIntervalSinceNow: -{{alerts.1.hoursAgo}} * 3600)),
    MonarchSecurityAlert(id: {{alerts.2.id}}, title: {{alerts.2.title}}, severity: {{alerts.2.severity|case}}, date: Date(timeIntervalSinceNow: -{{alerts.2.hoursAgo}} * 3600), isRead: {{alerts.2.read}}),
]

